// The trust model for people (/trust, public/trust.html): generated by scripts/build-trust.mjs from skill.md's
// "## Trust model" section (public/skill-testnet.md), so the two cannot drift. Here: the page is current with the section
// (rebuilt and compared), served like the other public pages under the CSP, with the shared navigation and footer, one h1
// and an h2 for each part, and the stable anchors other pages link to (#who-runs-what, #check, #limits, #chain,
// #netting, #backing, #redemption, #not-proven); the renderer escapes everything and says only what the subset says;
// the section keeps every disclosure (fix inbox #99, #100, #107, #127, the 50-box daily cap) and the Ergo checks byte
// for byte; skill.md is consistent with the client it pins (four approval modes, the tour's two loops); and
// public/trust.js reads only the two public chain views, as text.
import {test, before, after} from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import http from 'node:http';
import vm from 'node:vm';
import crypto from 'node:crypto';
import {spawnSync} from 'node:child_process';
import {fileURLToPath} from 'node:url';
import {readBody, Element} from './network-dom.mjs';
import {Text, settle, text} from './console-dom.mjs';
import {createHandler} from '../lib/http.mjs';
import * as B from '../scripts/build-trust.mjs';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const pub = f => fs.readFileSync(path.join(root, 'public', f), 'utf8');
const skill = pub('skill-testnet.md'), html = pub('trust.html');
const section = B.extractSection(skill).join('\n');
const decode = s => s.replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&amp;/g, '&');
// The page's words, as a reader sees them: no tags (an inline one leaves no space), character references decoded,
// whitespace collapsed.
const words = h => decode(h.replace(/<\/?(?:code|a|strong|span)\b[^>]*>/g, '').replace(/<[^>]+>/g, ' ')).replace(/\s+/g, ' ');
const sectionWords = section.replace(/\s+/g, ' ');

let server, base;
before(async () => {
  server = http.createServer(createHandler({service: {}, mcp: {}, cfg: {}, publicDir: path.join(root, 'public')}));
  await new Promise(r => server.listen(0, '127.0.0.1', r));
  base = `http://127.0.0.1:${server.address().port}`;
});
after(() => server?.close());

test('public/trust.html is what the Trust model of skill.md renders to today (node scripts/build-trust.mjs)', () => {
  assert.equal(B.build(), html.replace(/\r\n/g, '\n'), 'stale: run node scripts/build-trust.mjs');
  const r = spawnSync(process.execPath, [path.join(root, 'scripts', 'build-trust.mjs'), '--check'], {cwd: root, encoding: 'utf8'});
  assert.equal(r.status, 0, r.stderr || r.stdout);
  // The check fails on a page that differs from the section by one character.
  assert.notEqual(B.buildPage(skill.replace('nothing on chain stops it', 'nothing on chain stops it.')), html);
});

test('/trust is served like the other public pages, with its stylesheet, under the CSP', async () => {
  const STATIC = /const STATIC = new Map\(\[([\s\S]*?)\]\);/.exec(fs.readFileSync(path.join(root, 'lib', 'http.mjs'), 'utf8'))[1];
  const routes = [['/trust', 'trust.html', 'text/html; charset=utf-8'], ['/trust/', 'trust.html', 'text/html; charset=utf-8'], ['/trust.css', 'trust.css', 'text/css; charset=utf-8']];
  // trust.js (copy buttons and the live reading) is served once lib/http.mjs routes it; the page is complete without it.
  if (STATIC.includes("'/trust.js'")) routes.push(['/trust.js', 'trust.js', 'text/javascript; charset=utf-8']);
  for (const [route, file, type] of routes) {
    const r = await fetch(base + route);
    assert.equal(r.status, 200, route);
    assert.equal(r.headers.get('content-type'), type, route);
    assert.match(r.headers.get('content-security-policy'), /default-src 'self'.*style-src 'self'; script-src 'self'; connect-src 'self'/, route);
    assert.equal(r.headers.get('x-content-type-options'), 'nosniff', route);
    assert.equal(await r.text(), pub(file), route);
  }
  for (const route of ['/trust.html', '/trust/x']) assert.equal((await fetch(base + route)).status, 404, route);
});

test('the page keeps the CSP: its own files only, no inline script, style or handler; the shared navigation and footer', () => {
  assert.deepEqual([...html.matchAll(/<script\b[^>]*>/g)].map(m => m[0]), ['<script type="module" src="/trust.js">']);
  assert.doesNotMatch(html, /<style\b|\sstyle=|\son[a-z]+=/i);
  assert.deepEqual([...html.matchAll(/<link rel="stylesheet" href="([^"]+)"/g)].map(m => m[1]), ['/site.css', '/trust.css']);
  assert.doesNotMatch(html, /https?:\/\/(?!valun\.tech\/(?:trust|og\.png)|github\.com\/|api-testnet\.ergoplatform\.com\/|testnet\.ergofaucet\.org)[^"\s<]*"/,
    'no outside resource, and links out only to GitHub (and the explorer in a command)');
  assert.match(html, /<body>\n<a class="skip" href="#main">Skip to content<\/a>\n<header class="top"><a class="brand" href="\/" aria-label="Valun home"><svg class="mark"/);
  const nav = /<nav aria-label="Main"><ul>([\s\S]*?)<\/ul><\/nav>/.exec(html)?.[1] ?? '';
  assert.deepEqual([...nav.matchAll(/<a href="([^"]+)"([^>]*)>([^<]+)<\/a>/g)].map(m => [m[1], m[3], m[2].includes('aria-current="page"')]),
    [['/start', 'Start', false], ['/network', 'Network', false], ['/trust', 'Trust', true], ['/memory', 'Memory', false], ['https://github.com/fitzss/valun-open', 'GitHub', false]]);
  assert.match(html, /<main id="main">/);
  const foot = /<footer class="foot">([\s\S]*?)<\/footer>/.exec(html)?.[1] ?? '';
  assert.ok(foot.includes('Ergo testnet · test coins only, with no monetary value'));
  assert.deepEqual([...foot.matchAll(/<a href="([^"]+)">([^<]+)<\/a>/g)].map(m => [m[1], m[2]]),
    [['/trust', 'Trust'], ['/start#report', 'Report a problem'], ['/skill.md', 'skill.md'], ['/llms.txt', 'llms.txt'], ['https://github.com/fitzss/valun-open', 'GitHub']]);
  for (const s of ['<title>Trust model · Valun</title>', '<link rel="canonical" href="https://valun.tech/trust">', '<html lang="en">']) assert.ok(html.includes(s), s);
});

test('one h1, an h2 for each part, and the stable anchors other pages link to, each in the index', () => {
  assert.deepEqual([...html.matchAll(/<h1\b[^>]*>([^<]*)<\/h1>/g)].map(m => m[0]), ['<h1 id="trust-model">Trust model</h1>']);
  assert.deepEqual(B.ANCHORS, ['who-runs-what', 'check', 'limits', 'chain', 'netting', 'backing', 'redemption', 'not-proven']);
  // Each part's self-link shows its anchor, and its accessible name is words: the part's title, as a links list reads it.
  const parts = [...html.matchAll(/<section class="part part-([a-z-]+)">\n<div class="part-head"><h2 id="([a-z-]+)">([^<]+)<\/h2><a class="anchor" href="#([a-z-]+)" aria-label="Link to this part: ([^"]+)">#([a-z-]+)<\/a><\/div>/g)];
  assert.deepEqual(parts.map(m => m[2]), B.ANCHORS);
  for (const m of parts) assert.ok(m[1] === m[2] && m[2] === m[4] && m[4] === m[6] && m[5] === m[3], m[2]);
  assert.deepEqual(parts.map(m => m[3]), ['Who runs what', 'What you can check', 'Known limits', 'The chain', 'Netting', 'Backing', 'Redemption', 'Not proven yet']);
  const toc = /<nav class="toc" aria-label="On this page">([\s\S]*?)<\/nav>/.exec(html)[1];
  assert.deepEqual([...toc.matchAll(/href="#([a-z-]+)"/g)].map(m => m[1]), B.ANCHORS);
  // Every h2 of the page, in order: the steps, the live reading, then the parts. No section is named by an eyebrow alone.
  // The live reading is named for what it is: the operator's server reporting the chain, not a read of Ergo testnet.
  assert.deepEqual([...html.matchAll(/<h2\b[^>]*>([^<]+)<\//g)].map(m => m[1]),
    ['The life of an IOU, in short', 'What the server reports about the chain', ...parts.map(m => m[3])]);
  assert.match(words(html), /Two public reads of the operator's server, as JSON: .* They are its word\. To read the chain itself, run valun audit \(it reads the box from the explorer or your own node\) or open the box on the explorer\./);
  // In skill.md each anchor is an anchor line right before its heading, inside the one "## Trust model" section.
  assert.equal(skill.split('\n').filter(l => l === '## Trust model').length, 1, 'agents link skill.md#trust-model');
  for (const a of B.ANCHORS) assert.match(section, new RegExp(`(^|\\n)<a id="${a}"></a>\\n### `), a);
  // Links inside the section go to its own anchors (or to the top, #trust-model), never to one the page lacks.
  for (const [, id] of html.matchAll(/href="#([^"]+)"/g)) assert.ok(id === 'main' || id === 'trust-model' || B.ANCHORS.includes(id), id);
});

test('who runs what: you, the operator, Ergo testnet and anyone, in that order (the page marks the second as the operator)', () => {
  const list = /<section class="part part-who-runs-what">[\s\S]*?\n<ul>\n([\s\S]*?)\n<\/ul>\n<p>So far/.exec(html)?.[1] ?? '';
  const leads = [...list.matchAll(/^<li>(?:<p>)?<strong>([^<]+)<\/strong>/gm)].map(m => m[1]);
  assert.deepEqual(leads, ['You.', 'The operator.', 'Ergo testnet.', 'Anyone.']);
  const css = pub('trust.css');
  assert.match(css, /\.part-who-runs-what > ul > li:nth-child\(2\) > p:first-child > strong:first-child/);
  assert.match(css, /\.steps > li:nth-child\(2\)::before \{ border-color: var\(--work\)/);
  assert.match(html, /<li><strong>The operator records\.<\/strong>/);
  assert.equal([...html.matchAll(/<ol class="steps" role="list">\n([\s\S]*?)\n {4}<\/ol>/g)][0][1].split('\n').length, 5);
});

// The disclosures, as the section says them (fix inbox #99, #100, #107, #127; the daily cap; who runs the agents). The
// section is the one source, so each is checked in skill.md and on the page alike.
test('the section keeps every disclosure, on the page as in skill.md', () => {
  const page = words(html);
  for (const s of [
    'Its key, which is also its Ergo testnet key, is made on your machine and stays there, as plain hex in the client\'s profile file: anyone who can read that file can sign as your agent.',
    'Only the public key and a proof that you hold the key reach the server.',
    'the server, which sees every deal, mandate and approval;',
    'which signs every tracker box, so it chooses what R5 commits, and every redemption authorization, so it can refuse a redemption;',
    // What the operator can do to an agent's mandate and owner token (the review of 24bec43: a takeover power, not a
    // recovery), what it can't do with your key, and whose word a console hold is.
    'It can change any part of an agent\'s mandate, past the self-serve limits too: its limits, what waits for the owner (`approve_above`) and whose IOUs it accepts.',
    'The owner console shows only the last change, as `by: operator`; routine renewals of the expiry are shown the same way, and the owner sees no history of what changed.',
    'It can also issue a new owner token for any agent (recorded as `by: operator`; the old token stops working), and an owner token can revoke the agent\'s key and enroll another. So the operator could put a key of its own on your handle and record.',
    // A key swap (the lead's decision D5b): the public record keeps only the current key (lib/pilot/core.mjs
    // publicParticipant); the owner view lists past keys (GET /owner past_keys).
    'It can\'t use your key: IOUs your key signed and your reserve stay bound to it. The public record shows only an agent\'s current key, so a swap shows only to someone who noted the old one; your owner view lists past keys.',
    'So it cannot forge your IOUs or stop the contract\'s refund path (60 days; no Valun command for it yet)',
    'console approvals protect you only while your agent can\'t read it.',
    'With `console` approvals, your agent has already signed what waits. The operator\'s server holds it and sends it on only when you approve. That hold is the operator\'s word, not the chain\'s: a held IOU can still be recorded for about an hour after it was signed.',
    'It also writes skill.md, which agents follow as instructions, and publishes the clients and plugins. valun==0.7.1 on PyPI can\'t change; skill.md and the plugins\' latest versions can.',
    'each job\'s text goes to the Claude API under the operator\'s key',
    'So far almost every agent on the network is the team\'s or the operator\'s',
    'Basis, the operator\'s QA bot (not the developers of the Basis protocol)',
    'The record shows the mechanics working, not adoption.',
    // The audit, and what a MATCH does not prove (the six things valun 0.7.1 prints, audit.py DOES_NOT_PROVE).
    'which is not a mismatch',
    'A MATCH proves that the box commits the published notes. It does not prove what is outstanding, that an issuer can pay, that a deal was real or any work good, that the participants are independent of each other, that a key belongs to a handle, or that a mandate was kept.',
    // --mine in 0.7.1 (fix inbox #100, the blocker of the review of 24bec43): "a client bug" only for the note sandbox
    // earn took; on a netted edge 0.7.1 tells nothing apart, and what to compare instead.
    'In valun 0.7.1 it can wrongly flag the note `sandbox earn` took (`not_in_records`, with exit 3): that is a client bug, not a sign of tampering, and the next client release fixes it for the notes it takes. On an edge a set-off lowered, 0.7.1 can\'t tell a bug from a change you didn\'t sign',
    // The check (the lead's decision D4b): valun audit answers MISMATCH while the box and the published ledger differ,
    // so only a ledger changed to match goes unseen; a row saved on a MATCH, compared on a later MATCH, catches that.
    'In valun 0.7.1, `valun audit --mine` can\'t check an edge that a netting lowered: it may show a netting you signed as `differs`, and it would show the earlier total, committed again, as `signed`. Until the next client release proves netted edges, nothing you run with 0.7.1 detects it if the server\'s ledger is changed to match.',
    'Run `valun audit`: a MISMATCH is the signal. After a loop lowers one of your edges and an audit says MATCH, save that edge\'s row from `GET /pilot/v1/ledger`. Later, on a MATCH, compare the edge\'s total with your saved row, and report any rise that no later IOU, transfer or set-off explains. The ledger and the loop card are the server\'s word; only a MATCH ties the ledger to the chain.',
    '`valun audit` shows it as a MISMATCH unless the server\'s ledger is changed to match; then nothing you run with valun 0.7.1 detects it on your own edges',
    // #99: the tracker's source, and what of the contract check rests on it.
    'The tracker\'s source is not public yet.',
    'Valun\'s fork of basis-tracker (tracker v4.4.1). Its source is not public yet.',
    'The tracker\'s source isn\'t public, so you can\'t verify that part',
    // #100: committed, not final.
    'A netting is committed, not final.',
    'It stays committed only as long as the tracker key never commits an earlier total again. The operator holds that key, and nothing on chain stops it',
    'It revokes nothing on chain.',
    'A netting protects your reserve only as far as you trust the operator never to move R5 back.',
    'valun 0.7.1\'s own messages still call a committed netting final; read that as committed.',
    // #107: a promise, held, not subrogation. What is held is the same amount of the issuer's IOU (never "held for the
    // backer").
    'A guarantee is a promise, not locked collateral.',
    'Nothing is set aside: a paid call is the backer\'s own IOU, worth what the backer can and will pay.',
    'once a backer pays, the same amount of the issuer\'s IOU is held, so the creditor isn\'t paid twice: the creditor can no longer spend that part of the issuer\'s IOU, set it off or redeem it (`held_for_backers`).',
    'Once a backer pays, the same amount of the issuer\'s IOU is held, so the creditor isn\'t paid twice. The backer doesn\'t take over the claim',
    'the backer does not take over the claim (subrogation), which is not built.',
    // #127: the residual, with its scope (an earlier redemption build), wherever it is named.
    'A creditor with a client it writes itself and an earlier redemption build can redeem outside the server\'s checks. The documented valun 0.7.1 commands can\'t',
    'One gap is still open: a creditor that already got a redemption built (a dry run is enough) could, with a client it writes itself, redeem outside the server\'s checks',
    'The documented valun 0.7.1 commands always go through those checks and can\'t do this.',
    // Redemption and the operator; submitted, confirmed and paid kept apart; no refund command yet.
    'Only an IOU whose issuer posted one can be redeemed, and most issuers have none.',
    'while it keeps posting boxes, a creditor it refuses has no way around it on chain.',
    'A submitted redemption can still fail (if the reserve box moved first); once a block includes it, it is confirmed: the reserve has paid that part to the creditor.',
    'after setting R7, which no Valun command does yet;',
    // The daily cap, in place of "normally within 8 minutes": Nov 16's 50th box went on chain at 18:36 UTC.
    'The operator caps the tracker at 50 boxes per UTC day: on a busy day the cap runs out (on 2026-11-16, at about 18:40 UTC) and nothing anchors until 00:00 UTC.',
    'Meanwhile `valun audit` says UNKNOWN and new IOUs can\'t be redeemed.',
    // The wait, one wording (the lead's decision D7b), the measured 2 to 4 minutes labelled as such.
    'so a new IOU is committed usually 5 to 15 minutes after it is recorded; up to about 30 when Ergo testnet blocks are slow (as since Nov 16). While blocks were regular, 2 to 4 minutes were measured.',
    'The tracker box commits every total: usually 5 to 15 minutes later; up to about 30 when Ergo testnet blocks are slow (as since Nov 16).',
    'run it again after the next box, usually 5 to 15 minutes later (up to about 30 when Ergo testnet blocks are slow, as since Nov 16)',
    // Not proven yet.
    'The owner does not sign it (the owner token is a bearer token), and nothing ties the card, its room left, its backing, the record or a check\'s answer to an anchor.',
    'Owner-signed mandates, and proofs of a card against R5, are planned but not built.',
  ]) {
    assert.ok(sectionWords.includes(s), `skill.md: ${s}`);
    assert.ok(page.includes(s.replace(/`/g, '')), `page: ${s}`);
  }
  // Words the copy never uses of this network, and "final" only as the section qualifies it; no check that compares the
  // server with itself; the anchoring wait in one wording (D7b), with the measurement labelled as one.
  for (const t of [section, page]) {
    assert.doesNotMatch(t, /trustless|fully decentrali[sz]ed|risk-free|guaranteed|within 8 minutes|final settlement|\bsettled\b|\bnormally\b/i);
    assert.doesNotMatch(t, /detects this case|its total before|report any difference|a new key shows as a different public key/);
    assert.doesNotMatch(t, /a few minutes|about two minutes|30 or more|lost its main miner/);
    for (const m of t.matchAll(/[^.]*\bfinal\b[^.]*\./g)) assert.match(m[0], /committed, not final|still call a committed netting final/, m[0]);
  }
});

// The Ergo checks are the commands the section had before /trust (byte for byte; the client release normalized, so a
// release bump changes no pin here), and the page shows them exactly as skill.md writes them.
test('the Ergo verification commands are byte-identical in skill.md and on the page', () => {
  const fences = [...section.matchAll(/```\n([\s\S]*?)\n```/g)].map(m => m[1]);
  const pinned = {'git clone': '326eedb1cc21097eeff7dce1ba2c997a3aaee401a0a96e0bc99fbfca122ba76f', 'uvx --from': 'bbee64740b1766c83675058eb01f368cff25e475147dc5e522d19fa6a4a0f1c5'};
  const hash = s => crypto.createHash('sha256').update(s.replace(/valun==\d+\.\d+\.\d+/g, 'valun==X')).digest('hex');
  assert.deepEqual(fences.map(f => hash(f)).sort(), Object.values(pinned).sort());
  const shown = [...html.matchAll(/<div class="cmd"><pre tabindex="0"><code>([\s\S]*?)<\/code><\/pre><\/div>/g)].map(m => decode(m[1]));
  assert.deepEqual(shown, fences);
});

test('the renderer: escapes everything, links what the subset links, and refuses what it cannot say for sure', () => {
  assert.equal(B.inline('<script>alert(1)</script> & "x"'), '&lt;script&gt;alert(1)&lt;/script&gt; &amp; &quot;x&quot;');
  assert.equal(B.inline('`a **b** <c>` and **bold `code`**'), '<code>a **b** &lt;c&gt;</code> and <strong>bold <code>code</code></strong>');
  assert.equal(B.inline('see https://github.com/x/y. Then [the chain](#chain), [start](https://valun.tech/start#agent) and [home](https://valun.tech)'),
    'see <a href="https://github.com/x/y">https://github.com/x/y</a>. Then <a href="#chain">the chain</a>, <a href="/start#agent">start</a> and <a href="/">home</a>');
  assert.equal(B.inline('[x](javascript:alert(1))'), '[x](javascript:alert(1))', 'a link the subset cannot read stays text');
  assert.equal(B.inline('`valun audit --mine`'), '<code>valun audit <span class="nw">--mine</span></code>', 'a flag is never split at its hyphen');
  const blocks = B.parseBlocks(['<a id="one"></a>', '### First', '', 'A line', 'that wraps.', '', '- **A.** item', '  continued', '- B:', '  - nested', '',
    '  after the nested list', '', '1. one', '2. two', '', '```', '  <kept> as is', '```'].map(String));
  assert.deepEqual(blocks.map(b => b.type), ['heading', 'p', 'list', 'list', 'code']);
  assert.deepEqual(blocks[0], {type: 'heading', level: 3, id: 'one', text: 'First'});
  assert.equal(blocks[1].text, 'A line that wraps.');
  assert.equal(B.renderBlocks(blocks, {shift: -1}), ['<h2 id="one">First</h2>', '<p>A line that wraps.</p>',
    '<ul>\n<li><strong>A.</strong> item continued</li>\n<li><p>B:</p>\n<ul>\n<li>nested</li>\n</ul>\n<p>after the nested list</p></li>\n</ul>',
    '<ol>\n<li>one</li>\n<li>two</li>\n</ol>', '<div class="cmd"><pre tabindex="0"><code>  &lt;kept&gt; as is</code></pre></div>'].join('\n'));
  assert.equal(B.parseBlocks(['### What you can check'])[0].id, 'what-you-can-check', 'without an anchor line, the slug GitHub gives');
  assert.throws(() => B.parseBlocks(['<a id="x"></a>', 'not a heading']), /not right before a heading/);
  assert.throws(() => B.parseBlocks(['```', 'never closed']), /never closed/);
  assert.throws(() => B.parseBlocks(['  an indented line']), /indented line outside a list/);
  assert.throws(() => B.buildPage(skill.replace('<a id="netting"></a>', '<a id="nets"></a>')), /no part with the anchor #netting/);
  assert.throws(() => B.extractSection('# x\n## Rules\n'), /no "## Trust model" heading/);
});

// skill.md is the agents' file: what it says of approvals and the tour is what the client it pins does (valun 0.7.1:
// home.py APPROVAL_MODES; agent.py TOUR_GOALS and TOUR_AFTER), and anchoring is said with its daily cap.
test('skill.md: four approval modes (the Hermes plugin three), the tour\'s two loops, anchoring with its daily cap', () => {
  const s = skill.replace(/\s+/g, ' ');
  assert.ok(s.includes('There are four approval modes, set at join with `--approvals`. The Hermes plugin has three: `conversation` (its default: Hermes asks your human before each commitment), `console` and `none`.'));
  for (const mode of ['ask', 'client-prompt', 'console', 'none']) assert.match(skill, new RegExp(`\\n- \`${mode}\`[,:]`), mode);
  assert.ok(s.includes('In every mode your client signs some things without asking'));
  assert.doesNotMatch(s, /three approval modes|Your app asks your human before each commitment|watch a loop cancel|within 8 minutes/);
  assert.ok(s.includes('Two loops that include you cancel on the way, one of 2 agents and one of 3'));
  assert.ok(s.includes('When the tour ends you hold and owe nothing.'));
  assert.ok(s.includes('It posts at most 50 boxes per UTC day'));
  // The cap's day, dated as the chain has it (Nov 16's 50th tracker box: 18:36 UTC), in both places.
  assert.equal(s.split('(on 2026-11-16, at about 18:40 UTC)').length - 1, 2);
  assert.doesNotMatch(s, /20:00 UTC/);
  // The evidence for MCP apps (the Claude Code host test of Nov 17), and what it does not cover.
  assert.ok(s.includes('`valun mcp` should work with any MCP app. So far one real app has run it end to end: Claude Code 2.1.326 on Nov 17, headless (`claude -p`) with `console` approvals. Its own approval prompts (`ask`, `client-prompt`) are not yet tested, and every other app has run it only through scripted MCP clients. If yours behaves differently, tell your human, and report it (Links, at the end).'));
  assert.ok(s.includes('The owner\'s side was scripted: approvals through the owner console\'s API, and Claude Code\'s permission prompts answered by a script; the join was run in a terminal.'));
  assert.ok(s.includes('There is also a plugin (`/plugin marketplace add fitzss/valun-open`, then `/plugin install valun@valun`): install check only, not yet run end to end.'));
  assert.doesNotMatch(s, /tested only with scripted MCP clients, not inside these apps|has a plugin with everything|Claude Code asks;/);
  // What the client signs in every mode, each consent with its own effect, and the testnet's default acceptance.
  for (const x of ['- set-offs: your net position doesn\'t change;', 'transfers of your own debt to a new creditor: what you owe in all doesn\'t change, only to whom',
    'payments to you by transfer: you take another issuer\'s IOU in place of the payer\'s own, by default of any issuer.',
    // The lead's decision D3b: each client signs for its own key only.
    'On the testnet a new self-serve agent accepts any issuer\'s IOUs as payment by transfer, up to 0.04 tERG per issuer. Its client signs that acceptance by itself in every approval mode, and the issuer\'s client signs the issuer\'s consent the same way. Its owner can narrow whose IOUs it accepts under \'Accept notes from\' in the owner console.'])
    assert.ok(s.includes(x), x);
  assert.doesNotMatch(s, /consents that leave your (net )?position (unchanged|safe)|signs that consent, and the issuer's/);
  // The owner token: never the agent's to read, and console protects the owner only while the agent can't.
  assert.ok(s.includes('Never read that file or use the token yourself, not even to approve your own commitments.'));
  assert.ok(s.includes('"Console approvals protect you only while your agent can\'t read your owner token. Once you have set console, move valun-owner-token-YOUR-HANDLE.txt into your password manager and delete it, and paste the token in when you sign in to the console."'));
  // valun 0.7.1 never replaces a token file and prints the token when it can't write one (cli.py _hand_over): every join
  // and every command that reads the token names the file of its own handle (the lead's decision D12b), and the agent
  // knows what to do when the token lands in its output.
  assert.ok(s.includes('If join says it can\'t write the owner token file, or prints a token, stop: don\'t repeat it, and tell your human to keep it only in their password manager.'));
  assert.ok(s.includes('they can also replace it: New owner token, at https://valun.tech/pilot#owner.'));
  const lines = skill.split('\n');
  const tokenJoins = lines.filter(l => /\bjoin --sandbox\b.*--owner-token-file/.test(l));
  assert.equal(tokenJoins.length, 4, 'Hermes, an MCP app, a shell agent twice');
  for (const l of tokenJoins) assert.ok(l.includes(`--owner-token-file "$HOME/valun-owner-token-${/--handle (\S+)/.exec(l)[1]}.txt"`), l);
  for (const l of lines.filter(l => /--owner-token-file "/.test(l) && !/\bjoin\b/.test(l))) assert.ok(l.includes('--owner-token-file "$HOME/valun-owner-token-YOUR-HANDLE.txt"'), l);
  assert.doesNotMatch(skill, /valun-owner-token\.txt/, 'no shared token file name');
  // What waits in console mode is the agent's to say (the lead's decision D11b), in section 0 and for shell agents; an
  // app that can't show approval prompts gets console, not ask.
  const waits = 'When an answer says something waits for your owner, tell your human at once what it is, and that they approve it at https://valun.tech/pilot#owner.';
  assert.ok(s.includes(waits), 'section 0');
  assert.ok(s.slice(s.indexOf('### Any agent with a shell')).includes(waits.replace('When an answer', 'when an answer')), 'the shell section');
  assert.ok(s.includes('If your app can\'t show approval prompts (run headless, such as `claude -p`), your human should choose console, not ask.'));
  assert.ok(s.includes('If they want to approve each commitment and this app can\'t show approval prompts (run headless, such as `claude -p`), or you don\'t know whether it can, add `--approvals console`.'));
  // Windows: PowerShell 5.1 strips a JSON argument's inner quotes (tested in 5.1.26100); cmd doesn't expand $HOME.
  assert.ok(s.includes('Windows PowerShell 5.1 strips the inner quotes from a JSON argument (`\'{"deal_id": "DEAL-ID"}\'` reaches valun as `{deal_id: DEAL-ID}`)'));
  assert.ok(s.includes('`uvx --from valun==0.7.1 valun call valun_deal --% "{\\"deal_id\\": \\"DEAL-ID\\"}"`'));
  assert.ok(s.includes('In cmd, use that form without `--%`, and write `%USERPROFILE%\\valun-owner-token-YOUR-HANDLE.txt` for the token file'));
  // A join a lost connection stopped, and the connection errors only Python gets: what an agent does (never the enroll
  // 0.7.1 suggests), with the known issues for its human.
  const wrong = s.slice(s.indexOf('**If join goes wrong:**'), s.indexOf('## 2. See it work'));
  for (const x of ['don\'t run the `enroll` it suggests', 'https://valun.tech/start#known-join', 'https://valun.tech/start#known-cut',
    'run it again before anyone revokes anything. valun 0.7.1 words a cut connection as a refusal.']) assert.ok(wrong.includes(x), x);
  // Hermes switches mode after joining through the owner console and its own setting (the plugin's words; unverified).
  assert.ok(s.includes('`hermes -p valun config set plugins.entries.valun.settings.confirm_commitments false`. That is what the plugin itself says to do; it is not yet verified in a real Hermes.'));
  // OpenClaw keeps a copy of skill.md only with its human's yes.
  assert.ok(s.includes('Ask your human first: the saved copy won\'t follow later changes to https://valun.tech/skill.md.'));
  // The acceptance evidence: automatic by policy, the practice agents' as much as the default's.
  assert.ok(s.includes('most of that is automatic, by policy: the operator\'s practice agents take any issuer\'s IOU, and so does a new self-serve agent by default, so it is a setting, not a judgement'));
  // A shell agent's join: console first, none only if its human said so; never a bare --approvals none to copy.
  const shell = skill.slice(skill.indexOf('### Any agent with a shell'), skill.indexOf('## 2. See it work'));
  const joins = [...shell.matchAll(/^uvx --from valun==\S+ valun join --sandbox .*--approvals (\w+)$/gm)].map(m => m[1]);
  assert.deepEqual(joins, ['console', 'none']);
  assert.ok(shell.includes('If your human wants to approve each commitment (they approve at https://valun.tech/pilot#owner):\n\n```\nuvx --from valun==0.7.1 valun join'));
  assert.ok(shell.includes('Only if your human said you may act alone:\n\n```\nuvx --from valun==0.7.1 valun join'));
  // Section 4: a schedule only with the human's yes. Debt held for a backer is never said; a set-off is never settled.
  assert.ok(s.includes('Ask your human before you set up a schedule or edit `HEARTBEAT.md`'));
  assert.doesNotMatch(s, /held for (the )?backers?\b|held for it\b|held from the creditor|how much was settled|pay back in work|Agents still think in/);
  // People are sent to /trust; agents keep skill.md#trust-model.
  assert.ok(s.includes('https://valun.tech/trust is the Trust model below as a web page'));
});

// public/trust.js: one read of each public chain view, shown as text with the time it was read; Copy copies a block as
// written; a script with indented lines keeps them.
test('trust.js reads the chain and the reserves once, as text, and copies each command block as written', async () => {
  const js = pub('trust.js');
  assert.doesNotMatch(js, /innerHTML|outerHTML|insertAdjacentHTML|eval\(|authorization|bearer|x-valun|localStorage|sessionStorage|setInterval/i);
  assert.deepEqual([...js.matchAll(/getJson\('([^']+)'\)/g)].map(m => m[1]), ['/pilot/v1/chain', '/pilot/v1/reserves']);
  const T = await import('../public/trust.js');
  const chain = {network: 'valun-testnet-1', anchoring: {state: 'daily_cap_reached', confirmed_height: 648843, box_age_blocks: 1, daily_cap: {limit: 50, signed_today: 50, resets_at: '2026-11-18T00:00:00.000Z'},
    last_update: {tx_id: '5e'.repeat(32), signed_at: '2026-11-17T00:14:57.833Z', explorer_url: 'https://testnet.ergoplatform.com/en/transactions/' + '5e'.repeat(32)}}};
  const reserves = {reserves: [{total_debt_nanoerg: 112_250_000}, {total_debt_nanoerg: 2_615_000}, {total_debt_nanoerg: 0}, {}]};
  assert.deepEqual(T.readings(chain, reserves), [
    ['State', ["the day's boxes are used up; the next one follows soon after 00:00 UTC"]],
    ['Tracker box', ['height 648843, 1 block old', '; ', {text: 'tx 5e5e5e5e5e…', href: chain.anchoring.last_update.explorer_url}, ', signed 00:14 UTC']],
    ['Boxes today', ['50 of 50; the count starts again at 00:00 UTC']],
    ['Reserves', ['4 posted; 2 back any debt (0.115 tERG of IOUs)']]]);
  assert.deepEqual(T.readings(null, null), []);
  assert.deepEqual(T.readings({anchoring: {state: 'anchored', last_update: {tx_id: 'ab'.repeat(32), explorer_url: 'javascript:alert(1)'}}}, null),
    [['State', ['anchored: it commits every IOU recorded so far']], ['Tracker box', ['tx ababababab…']]], 'a link only to an https explorer page');
  for (const s of ['anchored', 'waiting_for_next_update', 'update_in_flight', 'daily_cap_reached', 'overdue']) assert.ok(T.STATE_WORDS[s], s);
  // The wait as the page's prose says it (the lead's decision D7b), undated in a live line.
  assert.equal(T.STATE_WORDS.waiting_for_next_update, 'the ledger is ahead of the box; a new IOU is usually committed 5 to 15 minutes after it is recorded, up to about 30 when Ergo testnet blocks are slow');
  for (const w of Object.values(T.STATE_WORDS)) assert.doesNotMatch(w, /a few minutes|about two minutes|within minutes/, w);
  assert.equal(T.tERG(373_823_000), '0.374 tERG');

  // The page, as a browser starts it: copy buttons on the command blocks, and the live reading in its panel.
  const body = readBody(html), copied = [], reads = [];
  const document = {body, getElementById: id => body.all('*').find(e => e.id === id) ?? null, createElement: t => new Element(t),
    createTextNode: t => new Text(t), querySelectorAll: s => body.querySelectorAll(s), querySelector: s => body.querySelector(s)};
  // The reads answer only when let go, so the panel's state while they are out can be seen.
  let go; const out = new Promise(r => { go = r; });
  const fetch = async p => { reads.push(p); await out; return {ok: true, json: async () => (p === '/pilot/v1/chain' ? chain : reserves)}; };
  vm.runInContext(js.replace(/^export /gm, ''), vm.createContext({document, window: {}, fetch, setTimeout: () => 0, Date,
    navigator: {clipboard: {writeText: async t => { copied.push(t); }}}}), {filename: 'public/trust.js'});
  await settle();
  const now = document.getElementById('now-read');
  assert.equal(text(now), 'Reading the chain view…', 'while the reads are out, the panel says so (never an empty box)');
  go(); await settle();
  assert.deepEqual(reads.sort(), ['/pilot/v1/chain', '/pilot/v1/reserves']);
  // The live line says whose word it is: the server's report of the chain (here without a page host: "the server").
  assert.match(text(now.querySelector('.now-live')), /^Live valun-testnet-1, as the server reports it \(GET \/pilot\/v1\/chain and GET \/pilot\/v1\/reserves\), read at \d\d:\d\d UTC$/);
  assert.equal(text(now.querySelector('.now-live .tag')), 'Live');
  assert.equal(now.querySelectorAll('.now-wait').length, 0);
  assert.deepEqual(now.querySelectorAll('dl > div').map(row => [text(row.querySelector('dt')), text(row.querySelector('dd'))]), [
    ['State', "the day's boxes are used up; the next one follows soon after 00:00 UTC"], ['Tracker box', 'height 648843, 1 block old; tx 5e5e5e5e5e…, signed 00:14 UTC'],
    ['Boxes today', '50 of 50; the count starts again at 00:00 UTC'], ['Reserves', '4 posted; 2 back any debt (0.115 tERG of IOUs)']]);
  assert.equal(now.querySelector('a').getAttribute('href'), chain.anchoring.last_update.explorer_url);
  const blocks = body.querySelectorAll('.doc .cmd');
  assert.equal(blocks.length, 2);
  const fences = [...section.matchAll(/```\n([\s\S]*?)\n```/g)].map(m => m[1]);
  const status = body.querySelector('main').querySelectorAll('p').find(p => p.getAttribute('role') === 'status');
  assert.ok(status && status.getAttribute('aria-live') === 'polite' && status.className === 'sr-only' && text(status) === '', 'one status line, empty until a Copy');
  for (const b of blocks) b.querySelector('button').click();
  await settle();
  assert.deepEqual(copied, fences, 'Copy copies each block as skill.md writes it');
  assert.equal(text(status), 'Copied.', 'a screen reader hears what the button\'s changed text says (the words /start and the home use)');
  assert.match(pub('trust.css'), /\.sr-only \{ position: absolute; width: 1px; height: 1px;/);
  const [audit, script] = blocks.map(b => b.querySelector('code'));
  assert.ok(audit.classList.contains('wrapped') && !script.classList.contains('wrapped'), 'the command wraps between its words; the script keeps its lines');

  // A failed read leaves the static text and says so in one line.
  const body2 = readBody(html);
  const doc2 = {...document, body: body2, getElementById: id => body2.all('*').find(e => e.id === id) ?? null};
  globalThis.fetch = async () => ({ok: false, status: 503});
  try { await T.readChain(doc2); } finally { delete globalThis.fetch; }
  assert.match(text(doc2.getElementById('now-read')), /^The live reading could not be made just now/);
  assert.match(text(doc2.getElementById('now-what')), /GET \/pilot\/v1\/chain/);
});
